#!/usr/bin/env bash
# Canvas Remote MCP — one-shot installer for an Oracle Cloud Ubuntu VM.
#
# GENERATED by deploy/bundle.sh from setup.template.sh + the repo files.
# Edit the template, then re-run bundle.sh. Don't hand-edit oracle-setup.sh.
#
# Usage (on the VM, e.g. via Oracle Cloud Shell -> ssh):
#   sudo bash oracle-setup.sh
#
# Safe to re-run: it updates the code and restarts, keeping your .env,
# OAuth state and HTTPS cert.
set -euo pipefail

APP_DIR=/opt/canvas-mcp
[ "$(id -u)" -eq 0 ] || { echo "Run with sudo: sudo bash $0"; exit 1; }

say() { printf '\n\033[1;36m==> %s\033[0m\n' "$*"; }

# --- 1. swap (the 1 GB micro VM needs it to build the image) ----------------
if [ "$(awk '/MemTotal/{print $2}' /proc/meminfo)" -lt 3000000 ] && ! swapon --show | grep -q /swapfile; then
  say "Adding 2 GB swap (small VM)"
  fallocate -l 2G /swapfile && chmod 600 /swapfile && mkswap /swapfile >/dev/null && swapon /swapfile
  grep -q /swapfile /etc/fstab || echo '/swapfile none swap sw 0 0' >> /etc/fstab
fi

# --- 2. docker ---------------------------------------------------------------
if ! command -v docker >/dev/null || ! docker compose version >/dev/null 2>&1; then
  say "Installing Docker"
  curl -fsSL https://get.docker.com | sh
fi
systemctl enable --now docker >/dev/null

# --- 3. OS firewall -------------------------------------------------------------
# Oracle's Ubuntu images ship an iptables REJECT rule that blocks 80/443 even
# after you open them in the VCN security list. Punch holes above it.
say "Opening ports 80 and 443 in the VM firewall"
for p in 80 443; do
  iptables -C INPUT -p tcp --dport "$p" -j ACCEPT 2>/dev/null \
    || iptables -I INPUT 5 -p tcp -m state --state NEW --dport "$p" -j ACCEPT
done
if command -v netfilter-persistent >/dev/null; then netfilter-persistent save >/dev/null 2>&1 || true; fi

# --- 4. app files -------------------------------------------------------------------
say "Writing app to $APP_DIR"
mkdir -p "$APP_DIR"
cd "$APP_DIR"
cat > server.py <<'__EOF_server_py__'
"""
Remote Canvas MCP server — OAuth-protected, cloud-hostable.

Wraps the stdio `canvas-lms-mcp` package in a FastMCP proxy and re-serves it
over Streamable HTTP with GitHub OAuth in front, so claude.ai / Cowork can
reach it with this machine off.

Why the odd-looking settings (all three are load-bearing for claude.ai web):
  - stateless_http=True + json_response=True : claude.ai web needs these
  - MCP mounted at "/" not "/mcp"             : claude.ai POSTs to the root
  - OAuthProxy under the hood (GitHubProvider): GitHub has no Dynamic Client
    Registration, and MCP clients require DCR; the proxy fakes a DCR-compliant
    face and forwards to GitHub.

Env vars (see .env.example):
  CANVAS_API_TOKEN, CANVAS_BASE_URL   -> passed to the upstream canvas server
  GITHUB_CLIENT_ID, GITHUB_CLIENT_SECRET
  BASE_URL                            -> public https URL of THIS server
  ALLOWED_GITHUB_USERS                -> comma-separated logins allowed in
  PORT                                -> injected by host (Fly/Railway/Render)
"""

import os

from fastmcp import FastMCP  # noqa: F401  (kept for type/context clarity)
from fastmcp.server import create_proxy
from fastmcp.server.auth.providers.github import GitHubProvider
from fastmcp.server.dependencies import get_access_token
from fastmcp.server.middleware import Middleware, MiddlewareContext
from mcp.types import ToolAnnotations  # noqa: F401  (kept for typing clarity)


def _require(name: str) -> str:
    val = os.environ.get(name)
    if not val:
        raise RuntimeError(f"Missing required env var: {name}")
    return val


CANVAS_API_TOKEN = _require("CANVAS_API_TOKEN")
CANVAS_BASE_URL = _require("CANVAS_BASE_URL")
BASE_URL = _require("BASE_URL").rstrip("/")
GITHUB_CLIENT_ID = _require("GITHUB_CLIENT_ID")
GITHUB_CLIENT_SECRET = _require("GITHUB_CLIENT_SECRET")

ALLOWED_USERS = {
    u.strip().lower()
    for u in os.environ.get("ALLOWED_GITHUB_USERS", "").split(",")
    if u.strip()
}
if not ALLOWED_USERS:
    raise RuntimeError(
        "ALLOWED_GITHUB_USERS is empty — refusing to start. Without an "
        "allowlist ANY GitHub user could drive your Canvas account."
    )

PORT = int(os.environ.get("PORT", "8000"))


class GitHubAllowlist(Middleware):
    """Second gate after OAuth: authenticating proves *a* GitHub identity,
    not that it's an identity we want. Reject everyone not on the allowlist."""

    async def on_call_tool(self, context: MiddlewareContext, call_next):
        token = get_access_token()
        login = None
        if token is not None:
            claims = getattr(token, "claims", None) or {}
            login = claims.get("login") or claims.get("preferred_username")
        if not login or login.lower() not in ALLOWED_USERS:
            raise ValueError(
                f"Access denied for GitHub user {login!r}. "
                "This server is restricted to its owner."
            )
        return await call_next(context)


auth = GitHubProvider(
    client_id=GITHUB_CLIENT_ID,
    client_secret=GITHUB_CLIENT_SECRET,
    base_url=BASE_URL,
)

# Proxy the upstream stdio canvas server. Its Canvas creds come from env here,
# so the token lives only in this process — never in the MCP conversation.
upstream = {
    "mcpServers": {
        "canvas": {
            "command": "canvas-lms-mcp",
            "args": [],
            "env": {
                "CANVAS_API_TOKEN": CANVAS_API_TOKEN,
                "CANVAS_BASE_URL": CANVAS_BASE_URL,
            },
        }
    }
}

mcp = create_proxy(
    upstream,
    name="Canvas (remote)",
    auth=auth,
)
mcp.add_middleware(GitHubAllowlist())


if __name__ == "__main__":
    # NOTE: stateless_http / json_response are http_app() options in FastMCP v3
    # (NOT constructor options) — they're forwarded via run()'s transport kwargs.
    # Both are required for claude.ai web to talk to a custom connector.
    mcp.run(
        transport="http",
        host="0.0.0.0",
        port=PORT,
        path="/",  # claude.ai posts to the root, not /mcp
        stateless_http=True,
        json_response=True,
    )
__EOF_server_py__
cat > requirements.txt <<'__EOF_requirements_txt__'
# Pinned: requirements used to say fastmcp>=2.12, so every rebuild silently
# jumped major versions (it was pulling 4.x). Bump deliberately, not by accident.
fastmcp>=4.0.10,<5
canvas-lms-mcp==0.1.2
uvicorn>=0.30
__EOF_requirements_txt__
cat > Dockerfile <<'__EOF_Dockerfile__'
FROM python:3.12-slim

ENV PYTHONUNBUFFERED=1 \
    PIP_NO_CACHE_DIR=1 \
    # OAuth state (Claude's client registration + issued tokens) lives here.
    # Must be a persistent volume — if it's wiped, the connector needs a reconnect.
    FASTMCP_HOME=/data

WORKDIR /app

COPY requirements.txt .
RUN pip install --no-cache-dir -r requirements.txt

COPY server.py .

ENV PORT=8000
EXPOSE 8000
VOLUME ["/data"]

CMD ["python", "server.py"]
__EOF_Dockerfile__
cat > docker-compose.yml <<'__EOF_docker_compose_yml__'
# Oracle Cloud (or any VM) deployment: the MCP server + Caddy for automatic HTTPS.
# Secrets come from .env next to this file (see .env.example). Never commit it.

services:
  canvas:
    build: .
    restart: unless-stopped
    env_file: .env
    environment:
      PORT: "8000"
      FASTMCP_HOME: /data
    volumes:
      - oauth-data:/data          # survives restarts/rebuilds -> no more reconnects
    expose:
      - "8000"                    # only reachable through Caddy, not the internet
    mem_limit: 400m               # fits the 1 GB E2.1.Micro with room to spare

  caddy:
    image: caddy:2
    restart: unless-stopped
    ports:
      - "80:80"
      - "443:443"
    environment:
      DOMAIN: ${DOMAIN}
    volumes:
      - ./Caddyfile:/etc/caddy/Caddyfile:ro
      - caddy-data:/data          # keeps the Let's Encrypt cert across restarts
    depends_on:
      - canvas

volumes:
  oauth-data:
  caddy-data:
__EOF_docker_compose_yml__
cat > Caddyfile <<'__EOF_Caddyfile__'
# Caddy gets and renews a Let's Encrypt cert for $DOMAIN automatically.
{$DOMAIN} {
	encode gzip
	reverse_proxy canvas:8000
}
__EOF_Caddyfile__

# --- 5. secrets (.env) — only asked the first time ----------------------------
if [ ! -f .env ]; then
  say "First-time setup: paste your secrets (input for secrets is hidden)"
  IP=$(curl -fsS https://api.ipify.org || true)
  DEFAULT_DOMAIN="${IP//./-}.sslip.io"
  read -rp  "Domain [$DEFAULT_DOMAIN]: " DOMAIN; DOMAIN=${DOMAIN:-$DEFAULT_DOMAIN}
  read -rsp "Canvas API token: " CANVAS_API_TOKEN; echo
  read -rp  "Canvas URL [https://yourschool.instructure.com]: " CANVAS_BASE_URL
  CANVAS_BASE_URL=${CANVAS_BASE_URL:-https://yourschool.instructure.com}
  read -rp  "GitHub OAuth client ID [Ov23linmhs7OYZsyGdG1]: " GITHUB_CLIENT_ID
  GITHUB_CLIENT_ID=${GITHUB_CLIENT_ID:-Ov23linmhs7OYZsyGdG1}
  read -rsp "GitHub OAuth client secret: " GITHUB_CLIENT_SECRET; echo
  read -rp  "Allowed GitHub users [Ashen00001]: " ALLOWED_GITHUB_USERS
  ALLOWED_GITHUB_USERS=${ALLOWED_GITHUB_USERS:-Ashen00001}
  umask 077
  cat > .env <<ENV
CANVAS_API_TOKEN=$CANVAS_API_TOKEN
CANVAS_BASE_URL=$CANVAS_BASE_URL
BASE_URL=https://$DOMAIN
DOMAIN=$DOMAIN
GITHUB_CLIENT_ID=$GITHUB_CLIENT_ID
GITHUB_CLIENT_SECRET=$GITHUB_CLIENT_SECRET
ALLOWED_GITHUB_USERS=$ALLOWED_GITHUB_USERS
ENV
  chmod 600 .env
fi
DOMAIN=$(grep '^DOMAIN=' .env | cut -d= -f2-)

# --- 6. start ----------------------------------------------------------------------
say "Building and starting (first build takes a few minutes)"
docker compose up -d --build

# --- 7. verify ---------------------------------------------------------------------
say "Waiting for HTTPS on https://$DOMAIN"
ok=""
for _ in $(seq 1 36); do
  if curl -fsS "https://$DOMAIN/.well-known/oauth-authorization-server" >/dev/null 2>&1; then ok=1; break; fi
  sleep 5
done
if [ -z "$ok" ]; then
  echo "HTTPS isn't up yet. Most likely the VCN security list doesn't allow 80/443."
  echo "Logs: cd $APP_DIR && docker compose logs --tail 50"
  exit 1
fi
code=$(curl -s -o /dev/null -w '%{http_code}' -X POST "https://$DOMAIN/" \
  -H 'Content-Type: application/json' -d '{"jsonrpc":"2.0","id":1,"method":"tools/list"}')
if [ "$code" != "401" ]; then
  echo "!! Unauthenticated request returned $code, expected 401. Server may be unprotected — stopping it."
  docker compose stop canvas; exit 1
fi

cat <<DONE

  Live and locked down:  https://$DOMAIN   (unauthenticated -> 401, good)

  Last two steps:
   1. GitHub OAuth app callback URL -> https://$DOMAIN/auth/callback
      https://github.com/settings/applications/3818524
   2. Claude -> Settings -> Connectors -> remove "canvas cloud", add a custom
      connector with URL
      https://$DOMAIN  and connect (GitHub login).

DONE
